interface.definition:
if(ri!showWhen <> false,
  a!localVariables(
    /*DEFAULTS*/
    local!actions: {
      #"_a-0000ec9b-212e-8000-9bae-011c48011c48_104783",
      #"_a-0000ec9b-212e-8000-9bae-011c48011c48_104789",
      #"_a-0000e77d-05a2-8000-9baf-011c48011c48_50214"
    },
    local!showLabel: a!defaultValue(value: ri!showLabel, default: false),
    local!align: a!defaultValue(value: ri!align, default: "END"),
    local!marginBelow: a!defaultValue(value: ri!marginBelow, default: "NONE"),
    local!isSubmit: a!defaultValue(value: ri!isSubmit, default: false),
    local!showActionMinimize: a!defaultValue(value: ri!showActionMinimize, default: true),
    local!showActionMaximize: a!defaultValue(value: ri!showActionMaximize, default: true),
    local!showActionClose: a!defaultValue(value: ri!showActionClose, default: false),

    /*DISPLAY*/
    #"SYSTEM_SYSRULES_ButtonArrayLayout"(
      buttons: {
        if(a!isNullOrEmpty(ri!additionalActions), {}, ri!additionalActions),
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: 
          if(local!showLabel,
            if(ri!selectedWindowControl = local!actions[1], 
              if(a!isNullOrEmpty(ri!label), 
              "Already minimized", 
              ri!label & " is minimized"
              ), 
              local!actions[1]
            ), ""
          ),
          icon: if(ri!selectedWindowControl = local!actions[1], "eye-slash", "eye"),
          width: "MINIMIZE",
          size: "SMALL",
          tooltip: 
          if(local!showLabel,
            "",
            if(ri!selectedWindowControl = local!actions[1], 
              if(
                a!isNullOrEmpty(ri!label),
                "Already minimized",
                ri!label & " is minimized"
              ), 
              local!actions[1]
            )
          ),
          value: if(ri!selectedWindowControl = local!actions[1], null, local!actions[1]),
          saveInto: {
            ri!selectedWindowControl,
            ri!saveInto
          },
          /*color: "#FDBE46",*/
          submit: local!isSubmit,
          style: if(ri!selectedWindowControl = local!actions[1], "SOLID", "OUTLINE"),
          showWhen: local!showActionMinimize
        ),
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: 
          if(local!showLabel,
            if(ri!selectedWindowControl = local!actions[2], 
              if(a!isNullOrEmpty(ri!label), 
                "Already expanded", 
                ri!label & " is expanded"
              ), 
              local!actions[2]
            ), ""
          ),
          icon: if(ri!selectedWindowControl = local!actions[2], "compress", "expand"),
          width: "MINIMIZE",
          size: "SMALL",
          tooltip: 
          if(local!showLabel,
            "",
            if(ri!selectedWindowControl = local!actions[2], 
              if(a!isNullOrEmpty(ri!label), 
                "Already expanded", 
                ri!label & " is expanded"
              ), 
              local!actions[2]
            )
          ),
          value: if(ri!selectedWindowControl = local!actions[2], null, local!actions[2]),
          saveInto: {
            ri!selectedWindowControl,
            ri!saveInto
          },
          /*color: "#FDBE46",*/
          submit: local!isSubmit,
          style: if(ri!selectedWindowControl = local!actions[2], "SOLID", "OUTLINE"),
          showWhen: local!showActionMaximize
        ),
        #"SYSTEM_SYSRULES_buttonWidget_v1"(
          label: 
          if(local!showLabel,
            local!actions[3],
            ""
          ),
          icon: "times",
          width: "MINIMIZE",
          size: "SMALL",
          tooltip: 
          if(local!showLabel,
            "",
            local!actions[3]
          ),
          value: if(ri!selectedWindowControl = local!actions[3], null, local!actions[3]),
          saveInto: {
            ri!selectedWindowControl,
            ri!saveInto
          },
          /*color: "#FC5C58",*/
          submit: local!isSubmit,
          showWhen: local!showActionClose
        )
      },
      showWhen: ri!selectedWindowControl <> local!actions[3],
      align: local!align,
      marginBelow: local!marginBelow
    )
  ), {}
)
